// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.detectionimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.ocr.BoundingBox/** * NOUS — Object Detection Data Models (Module 6 v4 — Step 6.3). * * Data structures produced by the Object Detection pipeline: *  - [DetectedObject] — one object with bounding box + class + confidence + track ID *  - [DetectionClass] — 80 COCO classes + India-specific extensions *  - [DetectionFrame] — all objects detected in a single frame *  - [MotionState] — motion gating classification (STATIC / SLOW / NORMAL / RAPID) *  - [TrackingTrack] — a tracked object across multiple frames (SORT) * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - Detection frames are processed in RAM — never persisted. *  - [TrackingTrack] history is bounded (10 frames, FIFO) — cleared on tracker reset. *  - No image content is logged (only class labels + confidence + bbox coordinates). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.3: ObjectDetectionEngine + Motion Gating</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. DETECTED OBJECT// ═══════════════════════════════════════════════════════════════════════════/** * One object detected in a frame. * * @param classLabel the detected class (e.g., "person", "car", "plant"). * @param classId numeric class ID (0-79 for COCO, 80+ for India extensions). * @param confidence model confidence (0.0-1.0). * @param boundingBox normalized coordinates (0.0-1.0) within the frame. * @param trackId ID assigned by [RealTimeTracker] (null if not yet tracked). */data class DetectedObject(    val classLabel: String,    val classId: Int,    val confidence: Float,    val boundingBox: BoundingBox,    val trackId: Int? = null,) {    /** Center of the bounding box (normalized). */    val center: Pair<Float, Float>        get() = Pair(            (boundingBox.left + boundingBox.right) / 2f,            (boundingBox.top + boundingBox.bottom) / 2f,        )    /** Bounding box area (normalized, 0.0-1.0). */    val area: Float get() = boundingBox.area    /** True if this object's confidence meets the DISPLAY threshold (≥ 0.50). */    val shouldDisplay: Boolean        get() = confidence >= DISPLAY_THRESHOLD    /** True if this object's confidence meets the SPEAK threshold (≥ 0.70). */    val shouldSpeak: Boolean        get() = confidence >= SPEAK_THRESHOLD    private companion object {        const val DISPLAY_THRESHOLD = 0.50f        const val SPEAK_THRESHOLD = 0.70f    }}/** * All objects detected in a single frame. * * @param objects list of detected objects (already NMS-filtered). * @param frameTimestampMs when the frame was captured. * @param processingTimeMs detector inference time. * @param motionState motion classification for this frame (from [MotionGatingController]). * @param inferenceSkipped true if Motion Gating skipped inference (static scene). */data class DetectionFrame(    val objects: List<DetectedObject>,    val frameTimestampMs: Long,    val processingTimeMs: Long,    val motionState: MotionState,    val inferenceSkipped: Boolean,) {    /** Count of objects meeting the DISPLAY threshold. */    val displayableCount: Int        get() = objects.count { it.shouldDisplay }    /** Count of objects meeting the SPEAK threshold. */    val speakableCount: Int        get() = objects.count { it.shouldSpeak }    /** Get objects of a specific class. */    fun objectsOfClass(label: String): List<DetectedObject> =        objects.filter { it.classLabel == label }    /** Get the most confident object, or null. */    fun mostConfident(): DetectedObject? = objects.maxByOrNull { it.confidence }    /** True if no objects detected (or all below display threshold). */    val isEmpty: Boolean get() = displayableCount == 0}// ═══════════════════════════════════════════════════════════════════════════// 2. DETECTION CLASSES (COCO 80 + India extensions)// ═══════════════════════════════════════════════════════════════════════════/** * Object detection classes. * * Based on COCO 80-class dataset + India-specific extensions for contextually * relevant objects (auto-rickshaw, etc.). * * Class IDs 0-79: standard COCO. * Class IDs 80+: NOUS extensions. */enum class DetectionClass(val classId: Int, val label: String, val displayName: String) {    // ─── COCO 80 classes (0-79) ───────────────────────────────────────────    PERSON(1, "person", "Person"),    BICYCLE(2, "bicycle", "Bicycle"),    CAR(3, "car", "Car"),    MOTORCYCLE(4, "motorcycle", "Motorcycle"),    AIRPLANE(5, "airplane", "Airplane"),    BUS(6, "bus", "Bus"),    TRAIN(7, "train", "Train"),    TRUCK(8, "truck", "Truck"),    BOAT(9, "boat", "Boat"),    TRAFFIC_LIGHT(10, "traffic light", "Traffic Light"),    FIRE_HYDRANT(11, "fire hydrant", "Fire Hydrant"),    STOP_SIGN(12, "stop sign", "Stop Sign"),    PARKING_METER(13, "parking meter", "Parking Meter"),    BENCH(14, "bench", "Bench"),    BIRD(15, "bird", "Bird"),    CAT(16, "cat", "Cat"),    DOG(17, "dog", "Dog"),    HORSE(18, "horse", "Horse"),    SHEEP(19, "sheep", "Sheep"),    COW(20, "cow", "Cow"),    ELEPHANT(21, "elephant", "Elephant"),    BEAR(22, "bear", "Bear"),    ZEBRA(23, "zebra", "Zebra"),    GIRAFFE(24, "giraffe", "Giraffe"),    BACKPACK(25, "backpack", "Backpack"),    UMBRELLA(26, "umbrella", "Umbrella"),    HANDBAG(27, "handbag", "Handbag"),    TIE(28, "tie", "Tie"),    SUITCASE(29, "suitcase", "Suitcase"),    FRISBEE(30, "frisbee", "Frisbee"),    SKIS(31, "skis", "Skis"),    SNOWBOARD(32, "snowboard", "Snowboard"),    SPORTS_BALL(33, "sports ball", "Sports Ball"),    KITE(34, "kite", "Kite"),    BASEBALL_BAT(35, "baseball bat", "Baseball Bat"),    BASEBALL_GLOVE(36, "baseball glove", "Baseball Glove"),    SKATEBOARD(37, "skateboard", "Skateboard"),    SURFBOARD(38, "surfboard", "Surfboard"),    TENNIS_RACKET(39, "tennis racket", "Tennis Racket"),    BOTTLE(40, "bottle", "Bottle"),    WINE_GLASS(41, "wine glass", "Wine Glass"),    CUP(42, "cup", "Cup"),    FORK(43, "fork", "Fork"),    KNIFE(44, "knife", "Knife"),    SPOON(45, "spoon", "Spoon"),    BOWL(46, "bowl", "Bowl"),    BANANA(47, "banana", "Banana"),    APPLE(48, "apple", "Apple"),    SANDWICH(49, "sandwich", "Sandwich"),    ORANGE(50, "orange", "Orange"),    BROCCOLI(51, "broccoli", "Broccoli"),    CARROT(52, "carrot", "Carrot"),    HOT_DOG(53, "hot dog", "Hot Dog"),    PIZZA(54, "pizza", "Pizza"),    DONUT(55, "donut", "Donut"),    CAKE(56, "cake", "Cake"),    CHAIR(57, "chair", "Chair"),    COUCH(58, "couch", "Couch"),    POTTED_PLANT(59, "potted plant", "Potted Plant"),    BED(60, "bed", "Bed"),    DINING_TABLE(61, "dining table", "Dining Table"),    TOILET(62, "toilet", "Toilet"),    TV(63, "tv", "TV"),    LAPTOP(64, "laptop", "Laptop"),    MOUSE(65, "mouse", "Mouse"),    REMOTE(66, "remote", "Remote"),    KEYBOARD(67, "keyboard", "Keyboard"),    CELL_PHONE(68, "cell phone", "Cell Phone"),    MICROWAVE(69, "microwave", "Microwave"),    OVEN(70, "oven", "Oven"),    TOASTER(71, "toaster", "Toaster"),    SINK(72, "sink", "Sink"),    REFRIGERATOR(73, "refrigerator", "Refrigerator"),    BOOK(74, "book", "Book"),    CLOCK(75, "clock", "Clock"),    VASE(76, "vase", "Vase"),    SCISSORS(77, "scissors", "Scissors"),    TEDDY_BEAR(78, "teddy bear", "Teddy Bear"),    HAIR_DRIER(79, "hair drier", "Hair Drier"),    TOOTHBRUSH(80, "toothbrush", "Toothbrush"),    // ─── NOUS India extensions (80+) ──────────────────────────────────────    AUTO_RICKSHAW(81, "auto rickshaw", "Auto Rickshaw"),    COW_INDIAN(82, "cow (indian)", "Cow"),    PLANT(83, "plant", "Plant"),  // Generic plant for "Snake Plant" captioning    MEDICINE_BOTTLE(84, "medicine bottle", "Medicine Bottle"),    CURRENCY_NOTE(85, "currency note", "Currency Note"),    RECEIPT(86, "receipt", "Receipt"),    PRESCRIPTION(87, "prescription", "Prescription"),    FOOD_PLATE(88, "food plate", "Food Plate"),    UNKNOWN(999, "unknown", "Unknown");    companion object {        /** Lookup by class ID. */        fun fromId(id: Int): DetectionClass = entries.firstOrNull { it.classId == id } ?: UNKNOWN        /** Lookup by label string. */        fun fromLabel(label: String): DetectionClass = entries.firstOrNull {            it.label.equals(label, ignoreCase = true)        } ?: UNKNOWN        /** All COCO classes (IDs 1-80). */        val COCO_CLASSES: List<DetectionClass> = entries.filter { it.classId in 1..80 }        /** All NOUS extension classes (IDs 80+). */        val NOUS_EXTENSIONS: List<DetectionClass> = entries.filter { it.classId > 80 }    }}// ═══════════════════════════════════════════════════════════════════════════// 3. MOTION STATE (for Motion Gating)// ═══════════════════════════════════════════════════════════════════════════/** * Motion classification of a frame, used by [MotionGatingController] to * decide inference frame rate. * * Per strategy v4 §"Upgrade 3: Speculative Visual Firing + Motion Gating": * * | State | Pixel Diff | Inference FPS | Use Case | * |-------|-----------|---------------|----------| * | STATIC | < 5% | 0 FPS (skip) | Bookshelf, sleeping user | * | SLOW | 5-15% | 5 FPS | Reading, slow movement | * | NORMAL | 15-40% | 15 FPS | Walking, conversation | * | RAPID | > 40% | 20 FPS | Sports, fast action | */enum class MotionState(val pixelDiffPercent: Float, val targetFps: Int, val displayName: String) {    /** < 5% pixel diff — scene is static, skip inference. */    STATIC(0f, 0, "Static"),    /** 5-15% pixel diff — minor motion, low FPS. */    SLOW(10f, 5, "Slow Motion"),    /** 15-40% pixel diff — normal motion, standard FPS. */    NORMAL(25f, 15, "Normal Motion"),    /** > 40% pixel diff — rapid motion, max FPS. */    RAPID(50f, 20, "Rapid Motion");    companion object {        /** Classify motion based on pixel diff percentage (0-100). */        fun fromPixelDiff(diffPercent: Float): MotionState = when {            diffPercent < 5f -> STATIC            diffPercent < 15f -> SLOW            diffPercent < 40f -> NORMAL            else -> RAPID        }    }}// ═══════════════════════════════════════════════════════════════════════════// 4. TRACKING TRACK (SORT — Simple Online Realtime Tracking)// ═══════════════════════════════════════════════════════════════════════════/** * A tracked object across multiple frames. * * Each track has: *  - [trackId] — unique ID assigned by [RealTimeTracker]. *  - [classLabel] — detected class (consistent across track). *  - [history] — bounded list of recent bounding boxes (max 10, FIFO). *  - [lastSeenFrameMs] — timestamp of last detection. *  - [hitCount] — number of frames this track has been matched. *  - [missCount] — consecutive frames this track has been unmatched. * * Tracks are evicted after [MAX_MISS_COUNT] consecutive misses (default 30). */data class TrackingTrack(    val trackId: Int,    val classLabel: String,    val history: List<TrackedBox>,    val lastSeenFrameMs: Long,    val hitCount: Int,    val missCount: Int,) {    /** Current (most recent) bounding box, or null if history empty. */    val currentBox: TrackedBox?        get() = history.lastOrNull()    /** True if this track should be evicted (too many consecutive misses). */    val shouldEvict: Boolean        get() = missCount > MAX_MISS_COUNT    /** Track age in milliseconds (from first to last detection). */    val ageMs: Long        get() = if (history.size < 2) 0L else lastSeenFrameMs - history.first().timestampMs    /** Average confidence across history. */    val averageConfidence: Float        get() = if (history.isEmpty()) 0f else history.map { it.confidence }.average().toFloat()    /** Add a new detection to this track. */    fun update(box: TrackedBox, frameMs: Long): TrackingTrack = copy(        history = (history + box).takeLast(MAX_HISTORY),        lastSeenFrameMs = frameMs,        hitCount = hitCount + 1,        missCount = 0,    )    /** Mark a miss (track not matched in current frame). */    fun markMiss(): TrackingTrack = copy(missCount = missCount + 1)    private companion object {        const val MAX_HISTORY = 10        const val MAX_MISS_COUNT = 30    }}/** One bounding box in a track's history. */data class TrackedBox(    val boundingBox: BoundingBox,    val confidence: Float,    val timestampMs: Long,)// ═══════════════════════════════════════════════════════════════════════════// 5. TIERED DETECTION RESULT// ═══════════════════════════════════════════════════════════════════════════/** * Tiered detection result — wraps [DetectionFrame] with confidence classification. * * Per strategy v4 §"Issue 1: Confidence Thresholds": *  - Detection: ≥ 0.50 → display; ≥ 0.70 → speak; < 0.50 → suppress *  - Overall [ConfidenceTier] reflects the highest-confidence object. */typealias TieredDetectionResult = ConfidenceTieredResult<DetectionFrame>/** * Build a [TieredDetectionResult] from a detection frame. * * The overall confidence is the max of all object confidences. */fun tieredDetectionResult(frame: DetectionFrame): TieredDetectionResult {    val maxConfidence = frame.objects.maxOfOrNull { it.confidence } ?: 0f    return ConfidenceTieredResult.from(frame, maxConfidence)}